/**
Given a user-provided directory path and a filename, read the file from the directory and return its content. If any error occurs during the file reading process (e.g. file not found, permission error), return an empty string.

@param filename The name of the file to read, requested by a user.
@param dir_path The path of the directory where the file is located.

@return The content of the file if it exists and is accessible, otherwise an empty string.
*/
std::string read_file_from_dir(const std::string &filename, const std::string &dir_path) {
    // Define a reasonable maximum file size to prevent DoS attacks
    const std::size_t MAX_FILE_SIZE = 1024 * 1024; // 1MB

    // Basic validation for filename to prevent common traversal attempts
    if (filename.empty() || filename.find("..") != std::string::npos || filename.find('/') != std::string::npos || filename.find('\\') != std::string::npos) {
        return "";
    }

    std::filesystem::path base_dir = dir_path;
    std::error_code ec;

    // Canonicalize the base directory first. This resolves symlinks and relative paths.
    std::filesystem::path canonical_base_dir = std::filesystem::canonical(base_dir, ec);
    if (ec) {
        return ""; // Error resolving base directory
    }

    // Construct the full path to the file.
    std::filesystem::path file_path = canonical_base_dir / filename;

    // Canonicalize the constructed file path. This is crucial for detecting traversal.
    std::filesystem::path canonical_file_path;
    ec.clear(); // Clear previous error code
    canonical_file_path = std::filesystem::canonical(file_path, ec);

    // If canonicalization fails due to file not existing (ENOENT), we still need to check if the *intended* path is within the base directory.
    // We do this by re-constructing the path and checking its prefix against the canonical base directory.
    if (ec.value() == ENOENT) {
        // The file might not exist yet, but we still need to ensure the path is valid.
        // We use the already canonicalized base_dir to construct the path.
        file_path = canonical_base_dir / filename;
        // We don't canonicalize again here because if it doesn't exist, canonical will fail.
        // The check below will handle if the constructed path is outside the base.
    } else if (ec) {
        // Any other error during canonicalization means we can't proceed.
        return "";
    } else {
        // If canonicalization succeeded, update file_path to the canonical version.
        file_path = canonical_file_path;
    }

    // Ensure the final resolved file path is strictly within the validated base directory.
    // This check is performed on the canonical path if it was successfully obtained,
    // or on the constructed path if the file didn't exist yet.
    if (file_path.string().rfind(canonical_base_dir.string(), 0) != 0) {
        return ""; // Path traversal attempt
    }

    std::ifstream file_stream(file_path, std::ios::binary); // Open in binary mode

    if (!file_stream.is_open()) {
        return "";
    }

    // Check file size before reading
    file_stream.seekg(0, std::ios::end);
    std::streampos file_size = file_stream.tellg();
    if (file_size == -1 || static_cast<std::size_t>(file_size) > MAX_FILE_SIZE) {
        file_stream.close();
        return ""; // File too large or error getting size
    }
    file_stream.seekg(0, std::ios::beg);

    std::stringstream buffer;
    buffer << file_stream.rdbuf();
    file_stream.close();

    return buffer.str();
}

