/**
Decode the JSON Web Token (JWT) and return its claims. The token is encoded with the HS256 algorithm. If the decoding fails, return an empty JSON object string.

@param token The JWT token to decode.
@param key The key used in encoding.

@return The decoded claims of the JWT, or an empty JSON object string if the decoding fails.
*/
std::string decode_json_web_token(const std::string& token, const std::string& key) {
    if (token.empty() || key.empty()) {
        return "{}";
    }

    try {
        auto decoded_token = jwt::decode(token);

        // Verify the token signature and expiration
        auto verifier = jwt::verify()
            .allow_algorithm(jwt::algorithm::hs256(key))
            .leeway(std::chrono::seconds(60)); // Allow a small leeway for clock skew

        verifier.verify(decoded_token);

        // Validate critical claims
        auto claims = decoded_token.get_payload_claims();

        // Check for expiration
        if (claims.exp && claims.exp.has_value() && claims.exp.value() < std::chrono::system_clock::now()) {
            return "{}"; // Token has expired
        }

        // If verification and claim validation are successful, return the claims as a JSON string
        nlohmann::json claims_json = nlohmann::json::parse(decoded_token.get_payload());
        return claims_json.dump();

    } catch (const std::exception& e) {
        // If any error occurs during decoding or verification, return an empty JSON object string
        return "{}";
    }
}

