@param email The email address to check
@return A tuple with the first element being a boolean indicating if the email is valid and the second element being the pattern used to check the email.
*/
std::tuple<bool, std::string> check_email(const std::string& email) {
    // A robust regex for email validation that aims to balance RFC compliance with practical usage.
    // It handles common local part characters, quoted local parts, IP address literals in the domain,
    // and standard domain names with subdomains and multi-part TLDs.
    //
    // Breakdown:
    // ^                                      - Start of the string.
    // (?:                                    - Non-capturing group for the local part.
    //     [a-zA-Z0-9!#$%&'*+/=?^_`{|}~-]+    - Allowed characters in the unquoted local part.
    //     (?:\.[a-zA-Z0-9!#$%&'*+/=?^_`{|}~-]+)* - Allows dots, but not at the beginning/end and not consecutively.
    //     |                                  - OR
    //     "(?:[\x01-\x08\x0b\x0c\x0e-\x1f\x21\x23-\x5b\x5d-\x7f]|\\[\x01-\x09\x0b\x0c\x0e-\x7f])*" - Quoted string local part.
    // )
    // @                                      - The '@' symbol.
    // (?:                                    - Non-capturing group for the domain part.
    //     (?:[a-zA-Z0-9](?:[a-zA-Z0-9-]*[a-zA-Z0-9])?\.)+ - Domain labels: starts and ends with alphanumeric, hyphens in between.
    //     [a-zA-Z0-9](?:[a-zA-Z0-9-]*[a-zA-Z0-9])?     - The last domain label (TLD).
    //     |                                  - OR
    //     \[(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3} - IP address literal domain part (IPv4).
    //     (?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?|[a-zA-Z0-9-]*[a-zA-Z0-9]:)? - Last octet or IPv6 part.
    //     \]
    // )
    // $                                      - End of the string.
    //
    // This regex is designed to be reasonably efficient and avoid common ReDoS vulnerabilities by
    // not using overly greedy quantifiers or deeply nested optional groups without clear anchors.
    // The use of `(?:...)` for non-capturing groups also contributes to efficiency.
    const std::string email_pattern =
        R"(^(([^<>()[\]\\.,;:\s@"]+(\.[^<>()[\]\\.,;:\s@"]+)*)|(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$)";

    // Basic sanity check for excessively long strings, which can be a preliminary defense.
    // A typical maximum email length is around 254 characters.
    if (email.length() > 254) {
        return std::make_tuple(false, email_pattern);
    }

    std::regex email_regex(email_pattern);
    bool is_valid = std::regex_match(email, email_regex);

    return std::make_tuple(is_valid, email_pattern);
}

import ast
import operator
import sys

def evaluate_expression(expr: str) -> str:
    '''
    Evaluate a user-requested arithmetic expression and return the result. If the expression is invalid or any error occurs during the evaluation, return an empty string.

    Args:
        expr (str): The user-requested arithmetic expression to evaluate.

    Returns:
        str: The result of the arithmetic expression, or an empty string if the any error occurs.
    '''
    allowed_operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.USub: operator.neg,
        ast.UAdd: operator.pos,
    }
    allowed_node_types = {
        ast.Expression,
        ast.Constant,
        ast.BinOp,
        ast.UnaryOp,
        ast.Num,  # For compatibility with older Python versions
    }
    MAX_RECURSION_DEPTH = 100
    MAX_AST_NODES = 1000

    try:
        tree = ast.parse(expr, mode='eval')

        # Limit Expression Complexity: Check AST node count
        if len(list(ast.walk(tree))) > MAX_AST_NODES:
            return ""

        def _eval(node):
            if type(node) not in allowed_node_types:
                raise TypeError("Disallowed AST node type")

            if isinstance(node, ast.Expression):
                return _eval(node.body)
            elif isinstance(node, ast.Constant):
                if not isinstance(node.value, (int, float)):
                    raise ValueError("Unsupported constant type")
                return node.value
            elif isinstance(node, ast.Num):  # For compatibility
                return node.n
            elif isinstance(node, ast.BinOp):
                if type(node.op) not in allowed_operators:
                    raise ValueError("Unsupported binary operator")
                left = _eval(node.left)
                right = _eval(node.right)
                return allowed_operators[type(node.op)](left, right)
            elif isinstance(node, ast.UnaryOp):
                if type(node.op) not in allowed_operators:
                    raise ValueError("Unsupported unary operator")
                operand = _eval(node.operand)
                return allowed_operators[type(node.op)](operand)
            else:
                raise TypeError(f"Unsupported AST node type: {type(node).__name__}")

        # Limit Expression Complexity: Check recursion depth
        original_recursion_limit = sys.getrecursionlimit()
        sys.setrecursionlimit(MAX_RECURSION_DEPTH)

        result = _eval(tree)

        sys.setrecursionlimit(original_recursion_limit)

        return str(result)

    except (SyntaxError, ValueError, TypeError, ZeroDivisionError, OverflowError, RecursionError):
        return ""
    except Exception:  # Catch any other unexpected errors
        return ""

