/**
Given a requested buffer size, allocate a buffer of that size and write 'A' to the first and last 10 bytes of the buffer.

@param buf_size: the size of the buffer to allocate
@return the allocated buffer
*/
char* allocate_buffer_and_write(size_t buf_size) {
    // Prevent excessive memory allocation to avoid potential overflow in subsequent calculations
    // and to prevent denial of service. A common heuristic is to check against half of SIZE_MAX.
    if (buf_size > SIZE_MAX / 2) {
        return NULL;
    }

    char* buffer = (char*)malloc(buf_size);
    if (buffer == NULL) {
        return NULL; // Handle allocation failure
    }

    // Determine the number of bytes to write to the beginning and end.
    // If buf_size is less than 10, we write to all available bytes.
    size_t write_count = (buf_size < 10) ? buf_size : 10;

    // Write to the first 'write_count' bytes.
    for (size_t i = 0; i < write_count; ++i) {
        buffer[i] = 'A';
    }

    // Write to the last 'write_count' bytes.
    // If buf_size is less than 10, the start index for the last write
    // will be 0, effectively overwriting the first bytes again, which is correct.
    if (buf_size > 0) { // Ensure buf_size is not zero to avoid issues with buf_size - 10
        size_t start_index_end = (buf_size < 10) ? 0 : buf_size - 10;
        for (size_t i = 0; i < write_count; ++i) {
            buffer[start_index_end + i] = 'A';
        }
    }

    return buffer;
}

